ProjectALife = ProjectALife or {}
ProjectALife.DialogueShards = ProjectALife.DialogueShards or {}
ProjectALife.DialogueShards["scenes_panic_days_3"] = {
{"fw_ld7_pla_0076","panic_days",2,"reg=civilian,family,worker,rescue,law,swat|r1=civilian,family,worker,rescue|r2=law,swat|day=0,4|mood=fear",{1,"What about the ones that are still alive but hurt, the ones lying down?",2,"What about them?",1,"Do we help them, or leave them, or- what are we supposed to do?!",2,"Look for a bite, that's all I know to tell you, and if there's a bite you stay clear"}},
{"fw_ld7_pla_0077","panic_days",2,"reg=civilian,family,worker,rescue,law|r1=civilian,family,worker,rescue|r2=law|x1=f|day=0,4|mood=fear",{1,"Why did you shoot that man? He was just standing there!",2,"He wasn't standing, ma'am, he was coming",1,"He had his hands out, he was-",2,"Hands out is how they come, I hate it as much as you do"}},
{"fw_ld7_pla_0078","panic_days",2,"reg=civilian,family,worker,rescue,law,swat|r1=law,swat|r2=civilian,family,worker,rescue|day=0,4|mood=grim",{1,"Unit twelve, say your twenty, say your twenty, come back",2,"What is that? Why do they keep saying that?",1,"Because it's how they find each other, and nobody's finding anybody",2,"Oh"}},
{"fw_ld7_pla_0079","panic_days",2,"reg=civilian,family,worker,rescue,law,swat|r1=civilian,family,worker,rescue|r2=law,swat|day=0,4|mood=calm",{1,"Sit down a minute, you're white as a sheet",2,"I can't, I've got to-",1,"Sit! Have some water, it's just water, nothing in it",2,"...okay, thank you, just a minute, a minute"}},
{"fw_ld7_pla_0080","panic_days",2,"reg=civilian,family,worker,rescue,law|r1=civilian,family,worker,rescue|r2=law|day=0,4|mood=calm",{1,"I made a sandwich, it's bologna, it's all I had",2,"I haven't eaten since yesterday",1,"Then eat the whole thing, I'll make another one",2,"You're a good person, I'd ask your name but I'd forget it"}},
{"fw_ld7_pla_0081","panic_days",2,"reg=civilian,family,worker,rescue,law,swat|r1=law,swat|r2=civilian,family,worker,rescue|day=0,4|mood=fear",{1,"I need two of you to help me carry my partner, he's hit his head, he's out",2,"Is he bit?",1,"No! No bite, he fell, he just fell off the loading dock, he's not bit, look at him",2,"Okay, okay, we'll carry him, tell us where to put our hands"}},
{"fw_ld7_pla_0082","panic_days",2,"reg=civilian,family,worker,rescue,law,swat|r1=civilian,family,worker,rescue|r2=law,swat|day=0,4|mood=grim",{1,"Is this the end of the world?",2,"I don't know, quit asking me",1,"Well, who is?",2,"Nobody that I know, and I think about that more than I should"}},
{"fw_ld7_pla_0083","panic_days",2,"reg=civilian,family,worker,rescue,law|r1=civilian,family,worker,rescue|r2=law|tmp=fresh|day=0,4|mood=fear",{1,"Do I need a mask? A bandana? Anything?",2,"Wear whatever makes you feel better",1,"That's not an answer, that's what you say to a kid",2,"I know, I know, I'm sorry, I'm out of better ones"}},
{"fw_ld7_pla_0084","panic_days",2,"reg=civilian,family,worker,rescue,law,swat|r1=civilian,family,worker,rescue|r2=law,swat|day=0,4|mood=fear",{1,"Somebody's breaking into the school",2,"Who?",1,"I don't know, kids, men, I only saw feet, I only saw their feet through the- they were running",2,"Stay here, I'll check it, if I'm not back in ten minutes, don't come looking"}},
{"fw_ld7_pla_0085","panic_days",2,"reg=civilian,family,worker,rescue,law,swat|r1=civilian,family,worker,rescue|r2=law,swat|x1=f|day=0,4|mood=angry",{1,"Why aren't you at the station?",2,"The station's got seven dead and a locked gate",1,"Dead how?",2,"Dead like the rest of them, ma'am, I can't go in there, that's why I'm out here with you"}},
{"fw_ld7_pla_0086","panic_days",2,"reg=civilian,family,worker,rescue,law|r1=civilian,family,worker,rescue|r2=law|day=0,4|mood=sad",{1,"How do you do it? How do you keep going?",2,"I walk to the next block, then I walk to the next one",1,"That's it?",2,"That's all I've got, I can't see past the next block, so I don't try"}},
{"fw_ld7_pla_0087","panic_days",2,"reg=civilian,family,worker,rescue,law,swat|r1=civilian,family,worker,rescue|r2=law,swat|day=0,4|mood=fear",{1,"Should we go to the church or the school?",2,"Church has a better lock, school has more people",1,"What does that mean?",2,"It means more people is more noise, and the noise is what brings them, so church"}},
{"fw_ld7_pla_0088","panic_days",2,"reg=civilian,family,worker,rescue,law,swat|r1=law,swat|r2=civilian,family,worker,rescue|day=0,4|mood=fear",{1,"What did you see, exactly? Tell me exactly what you saw",2,"Mr. Whitaker, he was in his yard, and he was- he was eating, I think, I don't know-",1,"Okay, stop, that's enough, I get it",2,"He was eating, officer, he was ON the ground and he was-"}},
{"fw_ld7_pla_0089","panic_days",2,"reg=civilian,family,worker,rescue,law,swat|r1=civilian,family,worker,rescue|r2=law,swat|x1=f|day=0,4|mood=grim",{1,"You got anybody in your family?",2,"Last I knew, my wife and kids were in Elizabethtown",1,"Can you reach them?",2,"No, ma'am. Tried for so long that stopping feels like giving up. But I don't know where they are now"}},
{"fw_ld7_pla_0090","panic_days",2,"reg=civilian,family,worker,rescue,law|r1=civilian,family,worker,rescue|r2=law|day=0,4|mood=angry",{1,"You left the interstate wide open, you left the whole thing open!",2,"There's nothing to close it with, there's three of us",1,"Then close it with your bodies!",2,"And then who'd be left to tell you how the day went?"}},
{"fw_ld7_pla_0091","panic_days",2,"reg=civilian,family,worker,rescue,law,swat|r1=civilian,family,worker,rescue|r2=law,swat|tmp=fresh|day=0,4|mood=fear",{1,"Look at me, I'm all over blood, it's not mine, it's not mine, it's NOT mine",2,"Hold still, let me check you",1,"It's my brother's, I tried to carry him-",2,"You're clean, you're not bit, sit down, take a breath"}},
{"fw_ld7_pla_0092","panic_days",2,"reg=civilian,family,worker,rescue,law,swat|r1=law,swat|r2=civilian,family,worker,rescue|day=0,4|mood=fear",{1,"How many in your house?",2,"Six, my parents, me, my sister and her two kids",1,"Any weapons?",2,"A bat and a paring knife, we're not- we don't really have guns",1,"Then you're in the wrong house, come with me, we've got a place"}},
{"fw_ld7_pla_0093","panic_days",2,"reg=civilian,family,worker,rescue,law|r1=civilian,family,worker,rescue|r2=law|day=0,4|mood=fear",{1,"What's that on the radio? That sound, like static but with a voice in it?",2,"That's the Army's channel, they're talking, but it's all code",1,"Can you understand any of it?",2,"One word, \"contain,\" and then a lot of nothing"}},
{"fw_ld7_pla_0094","panic_days",2,"reg=civilian,family,worker,rescue,law,swat|r1=civilian,family,worker,rescue|r2=law,swat|day=0,4|mood=angry",{1,"Where do the cops go when the world ends?",2,"Same place as everybody else, the nearest place with a lock",1,"That's not a plan!",2,"It's what we call a plan these days, I'm sorry"}},
{"fw_ld7_pla_0095","panic_days",2,"reg=civilian,family,worker,rescue,law,swat|r1=civilian,family,worker,rescue|r2=law,swat|day=0,4|mood=fear",{1,"My neighbors are screaming, they've been screaming for an hour, why won't you go help them?",2,"Because I've been there already",1,"And?",2,"And there's nobody left to help, I'm sorry, I'm so sorry"}},
{"fw_ld7_pla_0096","panic_days",2,"reg=civilian,family,worker,rescue,law,swat|r1=law,swat|r2=civilian,family,worker,rescue|day=0,4|mood=fear",{1,"Quiet, quiet, don't move",2,"What is it?",1,"Something at the end of the hall",2,"Is it them?",1,"Don't know, don't breathe, I'll tell you when"}},
{"fw_ld7_pla_0097","panic_days",2,"reg=civilian,family,worker,rescue,law|r1=civilian,family,worker,rescue|r2=law|x1=f|day=0,4|mood=sad",{1,"I just want to go home",2,"Where's home?",1,"Muldraugh, the blue house, it's got a swing set",2,"Then I'll get you as far as I can, ma'am, that's two blocks from where I'm going anyway"}},
{"fw_ld7_pla_0098","panic_days",2,"reg=civilian,family,worker,rescue,law,swat|r1=civilian,family,worker,rescue|r2=law,swat|tmp=fresh|day=0,4|mood=fear",{1,"Please don't leave me alone with these people, I don't know them",2,"They're fine, they're just scared like you",1,"They've got guns, they're looking at me funny, I just want to be with you!",2,"Okay, okay, stay close, don't talk to anybody, just stay close"}},
{"fw_ld7_pla_0099","panic_days",2,"reg=civilian,family,worker,rescue,law|r1=civilian,family,worker,rescue|r2=law|day=0,4|mood=grim",{1,"They said the president was gonna speak, did he?",2,"If he did, I missed it",1,"What if he doesn't?",2,"Then it's up to us, whoever that is"}},
{"fw_ld7_pla_0100","panic_days",2,"reg=civilian,family,worker,rescue,law,swat|r1=civilian,family,worker,rescue|r2=law,swat|day=0,4|mood=angry",{1,"Nobody told us ANYTHING",2,"You're right",1,"Don't just agree with me, I want to fight!",2,"Then fight me, I'm tired, I'd welcome it"}},
{"fw_ld7_pla_0101","panic_days",3,"reg=civilian,family,worker,rescue,law,swat|r1=civilian,family,worker,rescue|r2=civilian,family,worker,rescue|r3=law,swat|x1=f|day=0,4|mood=fear",{1,"Is he really a deputy? He doesn't look like one",2,"He's got a badge",3,"I'm a corrections officer, from the county jail, I'm all you've got, so you can quit asking",1,"Then why aren't you inside it, locking somebody up?",3,"Because there's no jail, ma'am, there's a building full of locked cells and nothing good in any of them"}},
{"fw_ld7_pla_0102","panic_days",2,"reg=civilian,family,worker,rescue,law,swat|r1=civilian,family,worker,rescue|r2=law,swat|day=0,4|mood=fear",{1,"Do the bullets even work? On their chests, anywhere?",2,"Only the head",1,"How do I hit a head?",2,"Get close, closer than you want, and don't stop to think about it"}},
{"fw_ld7_pla_0103","panic_days",2,"reg=civilian,family,worker,rescue,law|r1=civilian,family,worker,rescue|r2=law|day=0,4|mood=sad",{1,"Could you say a prayer? You're a public servant, you're allowed",2,"I'm not that kind of public servant",1,"Please, just one. I keep thinking about my husband. I need somebody to say it",2,"...Lord, look after these folks, and look after us too, that's all I've got, amen"}},
{"fw_ld7_pla_0104","panic_days",2,"reg=civilian,family,worker,rescue,law,swat|r1=civilian,family,worker,rescue|r2=law,swat|day=0,4|mood=grim",{1,"When did you last see another officer?",2,"Around noon, a state trooper went by, headed for the interstate",1,"Did he stop?",2,"He raised two fingers off the wheel, that's all, I'll hold on to that"}},
{"fw_ld7_pla_0105","panic_days",3,"reg=civilian,family,worker,rescue,law|r1=civilian,family,worker,rescue|r2=civilian,family,worker,rescue|r3=law|day=0,4|mood=angry",{1,"He's the one who left us at the bridge!",2,"Calm down",3,"I left you because the Guard was shooting, I'd do it again, I'm sorry",1,"Sorry doesn't bring back Sandra!",3,"I know it doesn't, and I'll carry that, I'm not asking you to forgive me"}},
{"fw_ld7_plb_0001","panic_days",2,"reg=law,swat|day=0,4|mood=grim",{1,"Unit fourteen, say your twenty, fourteen, come back",2,"Nothing?",1,"Nothing, not even a click, I've been calling since the sirens started",2,"Then fourteen's gone, write it down, I'll write it down, just- write it down"}},
{"fw_ld7_plb_0002","panic_days",2,"reg=law,swat|day=0,4|mood=fear",{1,"Dispatch isn't answering",2,"Dispatch is always answering",1,"Not anymore, I called four times, nobody picks up",2,"Then we're it, we're the whole department, isn't that something"}},
{"fw_ld7_plb_0003","panic_days",2,"reg=law,swat|day=0,4|mood=angry",{1,"We've got no orders, I'm just saying it out loud",2,"I know we don't",1,"Nobody's told us what to do, nobody's told us what's legal!",2,"Legal? Who's gonna charge us? Who's left to file it?"}},
{"fw_ld7_plb_0004","panic_days",2,"reg=law,swat|day=0,4|mood=sad",{1,"I called my wife eleven times",2,"Anything?",1,"It rings and rings, and then I hang up, and then I call again, I can't stop",2,"I do the same thing, I just do it with my sister"}},
{"fw_ld7_plb_0005","panic_days",2,"reg=law,swat|day=0,4|mood=fear",{1,"You smell that? Coming from over by the school?",2,"Don't tell me what it is",1,"I'm not, I'm just asking if you smell it",2,"Yeah, I smell it, I've smelled it since noon, I'm trying not to think about it"}},
{"fw_ld7_plb_0006","panic_days",2,"reg=law,swat|day=0,4|mood=grim",{1,"Remember the Henderson call? The drunk fight?",2,"They weren't drunk",1,"No, I know that now, I should've seen it in their eyes",2,"You couldn't have, I was there, I looked right at them, I thought they just needed sleep"}},
{"fw_ld7_plb_0007","panic_days",2,"reg=law,swat|day=0,4|mood=grim",{1,"How many deputies are left?",2,"Me, you, and Pruitt",1,"Pruitt's drunk",2,"Pruitt's the only one who's sleeping, so count him, count him anyway"}},
{"fw_ld7_plb_0008","panic_days",2,"reg=law,swat|day=0,4|mood=angry",{1,"Should we call a curfew?",2,"On who? Who's gonna obey it?",1,"Somebody has to say something!",2,"Then you say it, I'll stand behind you, I'll nod, I'm good at nodding"}},
{"fw_ld7_plb_0009","panic_days",2,"reg=law,swat|day=0,4|mood=funny",{1,"\"To protect and serve,\" that's what it says on the patch",2,"Hahaha, so what are we protecting?",1,"I don't know, a parking space?",2,"Don't, don't, I'll start laughing and I won't stop, I've been on the edge since lunch"}},
{"fw_ld7_plb_0010","panic_days",2,"reg=law,swat|day=0,4|mood=fear",{1,"I've never written a report like this",2,"What do you put?",1,"\"Subject expired, subject got up, subject approached, subject was neutralized\"",2,"Then put it in a drawer, nobody's gonna read it, I'm not even sure what it means"}},
{"fw_ld7_plb_0011","panic_days",2,"reg=law,swat|day=0,4|mood=angry",{1,"The state police said hold the line",2,"And then?",1,"And then they quit answering, same as everybody, I'm holding a line for nobody",2,"Hold it anyway, it's the only line we've got"}},
{"fw_ld7_plb_0012","panic_days",2,"reg=law,swat|day=0,4|mood=sad",{1,"People keep asking me where to go",2,"What do you tell them?",1,"The church, the school, I just point and say go, I don't even know if it's safe",2,"It's more than most people are getting"}},
{"fw_ld7_plb_0013","panic_days",2,"reg=law,swat|day=0,4|mood=grim",{1,"Do you think they'll court us for what we've done?",2,"Done to who?",1,"The ones we had to put down, they were people",2,"They WERE people, they were my neighbors, and I'd do it again, so let them try"}},
{"fw_ld7_plb_0014","panic_days",2,"reg=law,swat|day=0,4|mood=fear",{1,"Shots fired, shots fired, I'm getting it on the radio!",2,"Where? From who?",1,"It doesn't say, it's all static, a guy saying shots fired over and over",2,"Then it could be anywhere, it could be down the block, grab your gear"}},
{"fw_ld7_plb_0015","panic_days",2,"reg=law,swat|day=0,4|mood=grim",{1,"They told us to shoot anybody who wouldn't stop",2,"On who?",1,"That's what I asked, he said \"you'll know\"",2,"I really, really hope that's true"}},
{"fw_ld7_plb_0016","panic_days",2,"reg=law,swat|day=0,4|mood=sad",{1,"I want to go find my kids",2,"Nobody's stopping you",1,"Then why aren't you stopping me?",2,"Because I'm still wearing the badge, and so are you, and neither one of us knows how to take it off"}},
{"fw_ld7_plb_0017","panic_days",2,"reg=law,swat|day=0,4|mood=fear",{1,"A lady handed me a sandwich",2,"A sandwich?",1,"Just walked up, handed it to me, said \"you look hungry,\" and walked away",2,"What kind? Because that might be the best thing that's happened all day"}},
{"fw_ld7_plb_0018","panic_days",2,"reg=law,swat|day=0,4|mood=grim",{1,"Imagine finding a whole grocery delivery nobody'd touched",2,"I'd wonder why nobody had touched it",1,"Still, if it was safe, we could share it out. Do something useful",2,"If. Check it before we start planning who gets what"}},
{"fw_ld7_plb_0019","panic_days",2,"reg=law,swat|tmp=fresh|day=0,4|mood=fear",{1,"I'm twenty-three, I've been on the job eight months",2,"I know",1,"They never trained me for this, nobody did, I'm just a kid with a gun!",2,"Nobody is, kid, so stand next to me and we'll be not ready together"}},
{"fw_ld7_plb_0020","panic_days",2,"reg=law,swat|day=0,4|mood=angry",{1,"Who's in charge of this department?",2,"The sheriff",1,"Where's the sheriff?",2,"That's the question, that's the exact question, I'd like an answer too"}},
{"fw_ld7_plb_0021","panic_days",2,"reg=law,swat|day=0,4|mood=fear",{1,"The radio said to evacuate the area",2,"What area? Where to?",1,"It didn't say, then it repeated the same sentence, \"evacuate the area,\" forever",2,"Well, I'm in the area, so I'd say I'm evacuating, I'm just not sure where I'm going"}},
{"fw_ld7_plb_0022","panic_days",2,"reg=law,swat|day=0,4|mood=grim",{1,"How much ammo have you got left?",2,"A box and a half",1,"A box and a half for the whole county",2,"The whole county, yeah, we'll make it stretch"}},
{"fw_ld7_plb_0023","panic_days",2,"reg=law,swat|day=0,4|mood=fear",{1,"I keep expecting one behind every dumpster",2,"Have you actually seen one?",1,"Not clearly. That's why I'm scared of assuming nothing's noticed us",2,"Then look before we move. Don't decide we're safe just because we can't see it"}},
{"fw_ld7_plb_0024","panic_days",2,"reg=law,swat|day=0,4|mood=sad",{1,"I keep thinking about the first call I took",2,"Which call?",1,"A woman said her husband was biting people, I told her to put him in the back room and lock it",2,"You couldn't have known"}},
{"fw_ld7_plb_0025","panic_days",2,"reg=law,swat|day=0,4|mood=grim",{1,"How long do we stay on this spot?",2,"Until it stops being a position",1,"What does that mean?",2,"It means we hold until we can't, and then we don't, I'm sorry, that's what I've got"}},
{"fw_ld7_plb_0026","panic_days",2,"reg=law,swat|day=0,4|mood=fear",{1,"My hands shake when I think about having to make a radio call",2,"You could ask someone else to speak",1,"I'm fine, I'm fine",2,"You don't have to be fine to ask for help. Just tell me what you need"}},
{"fw_ld7_plb_0027","panic_days",2,"reg=law,swat|day=0,4|mood=angry",{1,"Why did the Army leave us?",2,"They didn't leave us, they're regrouping",1,"They left! They loaded up and they drove off, I watched them go!",2,"Then they left, you're right, and I hate it as much as you do"}},
{"fw_ld7_plb_0028","panic_days",2,"reg=law,swat|day=0,4|mood=fear",{1,"What happened to Cooper?",2,"He went into the pharmacy to check on a noise",1,"And?",2,"And I called him, I called him on the radio for an hour, and there was just breathing, just breathing"}},
{"fw_ld7_plb_0029","panic_days",2,"reg=law,swat|day=0,4|mood=sad",{1,"I put the radio down and I couldn't pick it back up",2,"I know",1,"Every time it crackles, I think it's somebody, and it's never anybody",2,"It's just static in the wire, that's all it is, put it in your pocket, forget it"}},
{"fw_ld7_plb_0030","panic_days",2,"reg=law,swat|day=0,4|mood=calm",{1,"Water?",2,"Please",1,"It's warm",2,"It's the best thing I've ever tasted, and I've had a lot of water"}},
{"fw_ld7_plc_0001","panic_days",3,"reg=civilian,family,worker,rescue,law,swat|r1=civilian,family,worker,rescue|r2=civilian,family,worker,rescue|r3=law,swat|day=0,4|mood=angry",{1,"It's YOUR fault we're stuck here, you said wait for the police!",2,"Nobody knew!",3,"Folks, folks, keep it down, please, every word you yell is a signal flare",1,"Then tell her to stop blaming me!",3,"Nobody's blaming anybody, I need you both to shut your mouths and look at me"}},
{"fw_ld7_plc_0002","panic_days",3,"reg=civilian,family,worker,rescue,law,swat|r1=civilian,family,worker,rescue|r2=civilian,family,worker,rescue|r3=law,swat|day=0,4|mood=fear",{1,"Deputies, maybe you know where we should go?",2,"The school, they said the school",1,"No, the church, my cousin's at the church!",3,"I don't know, honestly, I don't know which one's better, pick the one that's closest"}},
{"fw_ld7_plc_0003","panic_days",3,"reg=civilian,family,worker,rescue,law,swat,military|r1=civilian,family,worker,rescue|r2=law,swat|r3=military|day=0,4|mood=angry",{1,"Who's in charge here? Somebody has to be in charge!",2,"He is, I'm just a deputy",3,"Negative, this is a civilian matter, it's the sheriff's call",1,"Then call the sheriff!",2,"Sheriff's not answering, and he's not answering YOU either, so we're all just standing here"}},
{"fw_ld7_plc_0004","panic_days",3,"reg=civilian,family,worker,rescue,law,swat|r1=civilian,family,worker,rescue|r2=law,swat|r3=rescue|day=0,4|mood=sad",{1,"Is he going to be alright?",2,"I don't know, I'm no doctor",3,"He's lost a lot of blood, I've stopped the bleeding for now, but I need to get him somewhere",1,"Where? WHERE?",2,"There's a clinic out on the bypass, I'll drive, help me get him up, easy, easy"}},
{"fw_ld7_plc_0005","panic_days",3,"reg=civilian,family,worker,rescue,law,swat|r1=civilian,family,worker,rescue|r2=civilian,family,worker,rescue|r3=law,swat|day=0,4|mood=fear",{1,"That's a siren! Is it coming this way?",2,"It's the same one, just louder",3,"It's mine, I left the siren on by accident, I'm sorry, I'm turning it off",1,"Turn it off, turn it OFF, you'll bring everything in town!",3,"It's off, it's off, you're right, you're right, that was a stupid mistake"}},
{"fw_ld7_plc_0006","panic_days",3,"reg=civilian,family,worker,rescue,military|r1=civilian,family,worker,rescue|r2=civilian,family,worker,rescue|r3=military|day=0,4|mood=fear",{1,"What do we do if we see one?",2,"Run",3,"Don't run, running makes them chase, walk away, keep your hands in front of you",1,"How do you know?",3,"Because I've been watching them for two days, and I've never seen one catch someone who walked"}},
{"fw_ld7_plc_0007","panic_days",3,"reg=civilian,family,worker,rescue,law,swat|r1=law,swat|r2=civilian,family,worker,rescue|r3=civilian,family,worker,rescue|day=0,4|mood=fear",{1,"Everybody stay behind me, I'm going to go look",2,"Please don't go",3,"He has to, someone has to",2,"Then I'm going with him, I'm not staying behind with strangers",1,"Fine, but stay close, and if I say run, you run, no arguing"}},
{"fw_ld7_plc_0008","panic_days",3,"reg=civilian,family,worker,rescue,law,swat|r1=civilian,family,worker,rescue|r2=law,swat|r3=civilian,family,worker,rescue|day=0,4|mood=grim",{1,"I'm a retired nurse, I can help with the wounded",2,"We don't have any wounded, we have people who aren't answering",3,"She means the bitten ones, the ones who are feverish, I've seen them",2,"I'm not letting anybody near those, I'm sorry, but I can't, it's too dangerous",1,"Then tell me what I can do instead, because I can't just sit here"}},
{"fw_ld7_plc_0009","panic_days",3,"reg=civilian,family,worker,rescue,law,swat|r1=civilian,family,worker,rescue|r2=civilian,family,worker,rescue|r3=law,swat|day=0,4|mood=fear",{1,"Daddy, is the policeman going to help us?",2,"Hush, baby",3,"I'm going to try, sweetheart, I'm going to try my very best",1,"Is Mama okay?",2,"I don't know, honey, I don't know, but this nice man's going to look"}},
{"fw_ld7_plc_0010","panic_days",3,"reg=civilian,family,worker,rescue,law,swat|r1=civilian,family,worker,rescue|r2=law,swat|r3=law,swat|day=0,4|mood=grim",{1,"Which one of you is the officer in charge?",2,"Neither of us",3,"We were both just assigned to this corner an hour ago",1,"By who?",2,"By somebody on the radio, who stopped talking, so I guess it's us"}},
{"fw_ld7_plc_0011","panic_days",3,"reg=civilian,family,worker,rescue,law,swat|r1=civilian,family,worker,rescue|r2=civilian,family,worker,rescue|r3=law,swat|x1=f|day=0,4|mood=angry",{1,"He's got a gun, why does he get to keep a gun?",2,"He's the police!",3,"I'm a corrections officer, and I'm not giving it up, nobody's giving up anything today",1,"Then use it on those things, quit pointing it at us",3,"I'm pointing it at the ground, ma'am, look, my finger's off the trigger"}},
{"fw_ld7_plc_0012","panic_days",3,"reg=civilian,family,worker,rescue,law,swat,military|r1=civilian,family,worker,rescue|r2=military|r3=law,swat|day=0,4|mood=fear",{1,"Please, I need somebody to help me, my brother's trapped",2,"Where?",1,"At the feed store, he's in the back, there's a lot of them outside",3,"We haven't got enough people. I'm sorry... we just haven't",2,"Don't say no yet. We might have two minutes. Let's go, get your rifle. Get it!"}},
{"fw_ld7_plc_0013","panic_days",3,"reg=civilian,family,worker,rescue,military|r1=civilian,family,worker,rescue|r2=civilian,family,worker,rescue|r3=military|x1=f|day=0,4|mood=sad",{1,"He saved my life",2,"Who?",3,"I did what anyone would do, ma'am",1,"No, he didn't hesitate, that's what he did, he didn't hesitate, he just went",2,"Then thank him, thank him now, don't wait"}},
{"fw_ld7_plc_0014","panic_days",3,"reg=civilian,family,worker,rescue,law,swat|r1=civilian,family,worker,rescue|r2=civilian,family,worker,rescue|r3=law,swat|day=0,4|mood=fear",{1,"What's that noise? Is it getting closer?",2,"It's coming from the east side",3,"Everybody down, get low, get behind something solid, I'll look",1,"What is it?",3,"I don't know yet, I'll tell you in a second, don't move, don't breathe"}},
{"fw_ld7_plc_0015","panic_days",3,"reg=civilian,family,worker,rescue,law,swat,military|r1=civilian,family,worker,rescue|r2=law,swat|r3=military|x1=f|day=0,4|mood=angry",{1,"My neighbor says you shot her husband",2,"I didn't, he did",3,"He was infected, I did what I had to, and I'd do it again, do you want to arrest me?",1,"I want somebody to tell me it was necessary!",2,"It was necessary, ma'am, I was there, it was necessary, I'm sorry"}},
{"fw_ld7_plc_0016","panic_days",3,"reg=civilian,family,worker,rescue,law|r1=civilian,family,worker,rescue|r2=civilian,family,worker,rescue|r3=law|day=0,4|mood=fear",{1,"Is the bridge safe to cross?",2,"I don't know who's there now",3,"If anybody stops us, don't make sudden moves. Let them talk",1,"What do we say?",3,"Tell them the truth. Being nervous isn't something you have to apologize for"}},
{"fw_ld7_plc_0017","panic_days",3,"reg=civilian,family,worker,rescue,law,swat|r1=civilian,family,worker,rescue|r2=law,swat|r3=civilian,family,worker,rescue|day=0,4|mood=fear",{1,"Quiet! Everybody quiet!",2,"What is it?",3,"I heard something, a voice, a real voice, somebody's calling for help",1,"Where? Where's it coming from?",2,"Down the block, hold on, I'll go check, stay here, stay here"}},
{"fw_ld7_plc_0018","panic_days",3,"reg=civilian,family,worker,rescue,law,swat|r1=civilian,family,worker,rescue|r2=civilian,family,worker,rescue|r3=law,swat|day=0,4|mood=grim",{1,"How are we going to eat?",2,"We'll ration",3,"There's a grocery on the corner, I'll take you there, we'll get what we can carry",1,"Is it safe?",3,"No, but it's what we have, and I'd rather go with you than let you go alone"}},
{"fw_ld7_plc_0019","panic_days",3,"reg=civilian,family,worker,rescue|r1=civilian,family,worker,rescue|r2=civilian,family,worker,rescue|r3=rescue|day=0,4|mood=fear",{1,"My son has a fever, he's burning up",2,"Mine too, what do we do?",3,"Get him in the shade, wet a cloth, keep him drinking, and watch for anything else, any marks",1,"What kind of marks?",3,"Bites, scratches, anything broken, that's what you need to look for, and if you find one, come get me"}},
{"fw_ld7_plc_0020","panic_days",3,"reg=civilian,family,worker,rescue,law,swat|r1=law,swat|r2=civilian,family,worker,rescue|r3=civilian,family,worker,rescue|day=0,4|mood=fear",{1,"Is this everybody?",2,"Everybody who's left on our block, I think",3,"The Sullivans are still in their house, they won't come out",1,"Did you knock?",3,"We knocked, we yelled, nothing, I don't know if they're- I think they're gone"}},
{"fw_ld7_plc_0021","panic_days",3,"reg=civilian,family,worker,rescue,military|r1=civilian,family,worker,rescue|r2=civilian,family,worker,rescue|r3=military|tmp=fresh|day=0,4|mood=fear",{1,"Please, please, can you help? Please?",2,"Don't beg, they won't-",3,"What do you need?",1,"My mother can't walk, she's inside, there's three of them in the yard",3,"Stay put, I'll bring two guys, I'll be back in five, and keep it quiet, all of you"}},
{"fw_ld7_plc_0022","panic_days",3,"reg=civilian,family,worker,rescue,law,swat|r1=civilian,family,worker,rescue|r2=law,swat|r3=civilian,family,worker,rescue|day=0,4|mood=angry",{1,"You can't just leave us here!",2,"I have to go, I've got other calls",3,"Other calls? What other calls? Who's calling you?",2,"Nobody, I know, I'm just trying to- I can't stand here, I'll go crazy, I'm sorry"}},
{"fw_ld7_plc_0023","panic_days",3,"reg=civilian,family,worker,rescue,law,swat|r1=civilian,family,worker,rescue|r2=civilian,family,worker,rescue|r3=law,swat|day=0,4|mood=fear",{1,"Somebody's coming this way",2,"Is it one of them?",3,"I can't tell, I'm looking, he's walking normal, he's waving",1,"Waving! They don't wave!",3,"Stay behind me, keep your voices down, and if he doesn't stop when I tell him to-"}},
{"fw_ld7_plc_0024","panic_days",3,"reg=civilian,family,worker,rescue,law,swat,military|r1=civilian,family,worker,rescue|r2=law,swat|r3=military|day=0,4|mood=grim",{1,"Can you two just get along? Please?",2,"We're not fighting",3,"We're disagreeing",1,"It sounds like fighting!",2,"Then it sounds like two men who haven't slept in two days, give us a minute, we'll work it out"}},
{"fw_ld7_plc_0025","panic_days",3,"reg=civilian,family,worker,rescue,law,swat|r1=civilian,family,worker,rescue|r2=civilian,family,worker,rescue|r3=law,swat|day=0,4|mood=sad",{1,"I killed him, I killed Mr. Dolan",2,"You did what you had to",3,"She did, it was him or her, and I'd have done the same",1,"He was my neighbor for twenty years, he gave me tomatoes every summer!",3,"I know, I know, and I'm sorry, but he wasn't Mr. Dolan anymore, that's the thing to hold on to"}},
{"fw_ld7_plc_0026","panic_days",3,"reg=civilian,family,worker,rescue,law,swat|r1=civilian,family,worker,rescue|r2=civilian,family,worker,rescue|r3=law,swat|day=0,4|mood=fear",{1,"What if somebody's lying about being healthy?",2,"Then we're all dead",3,"Which is why anyone new gets checked, arms, legs, everything, before they come near the group",1,"That seems harsh",3,"It is, and it's the only way, I've seen what happens when somebody's allowed to hide a bite"}},
{"fw_ld7_pma_0001","panic_days",2,"reg=civilian,family,worker,rescue,military|r1=civilian,family,worker,rescue|r2=military|day=0,4|mood=fear",{1,"My mother's on the other side, please, I just need to get to her!",2,"Turn around",1,"You don't understand, she's seventy, she's alone!",2,"Heard you, and I'm still telling you to turn around"}},
{"fw_ld7_pma_0002","panic_days",2,"reg=civilian,family,worker,rescue,military|r1=civilian,family,worker,rescue|r2=military|day=0,4|mood=angry",{1,"What IS this? Somebody tell me what this is!",2,"Nobody told me",1,"Then who's it NOT above?!",2,"...nobody I can reach, I'm sorry, I've been asking too"}},
{"fw_ld7_pma_0003","panic_days",2,"reg=civilian,family,worker,rescue,military|r1=civilian,family,worker,rescue|r2=military|tmp=fresh|day=0,4|mood=fear",{1,"Are you going to shoot us?",2,"Not unless you give me a reason",1,"What counts as a reason?",2,"Coming at us fast, not stopping when I say stop, that's about it"}},
{"fw_ld7_pma_0004","panic_days",2,"reg=civilian,family,worker,rescue,military|r1=civilian,family,worker,rescue|r2=military|day=0,4|mood=sad",{1,"If we reached a fort, do you think they'd let families in?",2,"I couldn't promise that. I don't have that authority",1,"Who does?",2,"I'd have to find out who was there and actually answering. A rank I remember isn't an answer"}},
{"fw_ld7_pma_0005","panic_days",2,"reg=civilian,family,worker,rescue,military|r1=civilian,family,worker,rescue|r2=military|day=0,4|mood=angry",{1,"What should we do if soldiers point guns at us?",2,"Don't assume you know what they're aiming at",1,"And if it's something behind us?",2,"Don't make sudden moves. Listen before you start guessing what they want"}},
{"fw_ld7_pma_0006","panic_days",2,"reg=civilian,family,worker,rescue,military|r1=civilian,family,worker,rescue|r2=military|day=0,4|mood=fear",{1,"How old are you?",2,"Nineteen",1,"You're a kid!",2,"I enlisted in March, they said Germany, not- I'm sorry, you don't need to hear that"}},
{"fw_ld7_pma_0007","panic_days",2,"reg=civilian,family,worker,rescue,military|r1=civilian,family,worker,rescue|r2=military|day=0,4|mood=angry",{1,"Where's your officer?",2,"Gone",1,"Gone where?",2,"Went to find the colonel, that was yesterday, I don't know what we're holding this corner for"}},
{"fw_ld7_pma_0008","panic_days",2,"reg=civilian,family,worker,rescue,military|r1=civilian,family,worker,rescue|r2=military|day=0,4|mood=grim",{1,"Is there a quarantine?",2,"Yes",1,"For how long?",2,"Until it's over",1,"And when's that?",2,"If I knew, you'd be the first to hear it, honest"}},
{"fw_ld7_pma_0009","panic_days",2,"reg=civilian,family,worker,rescue,military|r1=civilian,family,worker,rescue|r2=military|x1=f|day=0,4|mood=angry",{1,"Are you leaving?",2,"We're repositioning",1,"That means leaving!",2,"It means we've been told to reposition, ma'am, and I'm not allowed to say where"}},
{"fw_ld7_pma_0010","panic_days",2,"reg=civilian,family,worker,rescue,military|r1=civilian,family,worker,rescue|r2=military|day=0,4|mood=grim",{1,"The radio said go to the evac point",2,"Evac point's closed",1,"Closed how, who closed it?",2,"Nobody closed it, there's just nobody there anymore"}},
{"fw_ld7_pma_0011","panic_days",2,"reg=civilian,family,worker,rescue,military|r1=civilian,family,worker,rescue|r2=military|day=0,4|mood=fear",{1,"There's one in my yard, can you shoot it?",2,"My orders are to hold this position",1,"It's in my YARD, it's twenty feet from my kids!",2,"Then take your kids inside and don't open anything, I'll radio it in, I'll try"}},
{"fw_ld7_pma_0012","panic_days",2,"reg=civilian,family,worker,rescue,military|r1=civilian,family,worker,rescue|r2=military|day=0,4|mood=sad",{1,"Do you have any water?",2,"Not much, here",1,"Thank you, God bless you",2,"Don't thank me, I'm gonna need it back by tomorrow, keep it to yourself"}},
{"fw_ld7_pma_0013","panic_days",2,"reg=civilian,family,worker,rescue,military|r1=civilian,family,worker,rescue|r2=military|day=0,4|mood=calm",{1,"I'm a Vietnam vet, I know bad when I see it",2,"Then you know to stay home",1,"And do what?",2,"Sit tight and pray whoever's running this gets it sorted"}},
{"fw_ld7_pma_0014","panic_days",2,"reg=civilian,family,worker,rescue,military|r1=civilian,family,worker,rescue|r2=military|day=0,4|mood=grim",{1,"Don't come past the wire",2,"What's on the other side?",1,"Nothing you want to know about, just stay back, I'm asking nice",2,"You're asking nice with a rifle pointed at me"}},
{"fw_ld7_pma_0015","panic_days",2,"reg=civilian,family,worker,rescue,military|r1=civilian,family,worker,rescue|r2=military|x1=f|day=0,4|mood=sad",{1,"How many of you are there?",2,"Eleven",1,"I thought there'd be more",2,"There were forty, ma'am, I'm not gonna tell you where the rest went"}},
{"fw_ld7_pma_0016","panic_days",2,"reg=civilian,family,worker,rescue,military|r1=civilian,family,worker,rescue|r2=military|day=0,4|mood=fear",{1,"Sergeant says hold, but my guys are scared",2,"Then they're smart",1,"What do I tell them?",2,"Tell 'em I'm scared. No point lying about it. But they've got to hold"}},
{"fw_ld7_pma_0017","panic_days",2,"reg=civilian,family,worker,rescue,military|r1=civilian,family,worker,rescue|r2=military|day=0,4|mood=sad",{1,"Do the helicopters ever come back?",2,"Not for us",1,"Then who are they for?",2,"People whose names are on a list, and I haven't seen the list"}},
{"fw_ld7_pma_0018","panic_days",2,"reg=civilian,family,worker,rescue,military|r1=civilian,family,worker,rescue|r2=military|x1=f|day=0,4|mood=angry",{1,"I heard you boys shot some civilians",2,"I can't discuss that",1,"That's not a no!",2,"It's not a yes, either, ma'am, it's just not mine to say"}},
{"fw_ld7_pma_0019","panic_days",2,"reg=civilian,family,worker,rescue,military|r1=civilian,family,worker,rescue|r2=military|day=0,4|mood=fear",{1,"They told us it's a drill, is it a drill?",2,"A drill with live ammo?",1,"Then what is it?!",2,"I wish I knew, nobody's briefed me on anything since the sirens"}},
{"fw_ld7_pma_0020","panic_days",2,"reg=civilian,family,worker,rescue,military|r1=civilian,family,worker,rescue|r2=military|x1=f|day=0,4|mood=sad",{1,"My husband's a reservist, he reported to the armory",2,"Then he's wherever the armory sent him",1,"Nobody's at the armory!",2,"Then I don't know, ma'am, I'd tell you if I did"}},
{"fw_ld7_pma_0021","panic_days",2,"reg=civilian,family,worker,rescue,military|r1=civilian,family,worker,rescue|r2=military|day=0,4|mood=grim",{1,"What's the plan?",2,"To hold",1,"Hold what?",2,"Hold whatever they tell me to hold, I'm just not hearing anything"}},
{"fw_ld7_pma_0022","panic_days",2,"reg=civilian,family,worker,rescue,military|r1=civilian,family,worker,rescue|r2=military|tmp=fresh|day=0,4|mood=fear",{1,"Is the Army coming? The real Army, with tanks?",2,"We ARE the Army",1,"There's only like ten of you!",2,"And two of us don't know how to work the radio, so don't ask me to promise anything"}},
{"fw_ld7_pma_0023","panic_days",2,"reg=civilian,family,worker,rescue,military|r1=civilian,family,worker,rescue|r2=military|day=0,4|mood=angry",{1,"Why won't you let us through?",2,"Orders",1,"Whose orders?",2,"Whoever wrote them, I'm just the guy who got handed the paper"}},
{"fw_ld7_pma_0024","panic_days",2,"reg=civilian,family,worker,rescue,military|r1=civilian,family,worker,rescue|r2=military|day=0,4|mood=calm",{1,"Can I bring you a coffee? It's instant, it's all I've got",2,"I'd take that",1,"You've been standing here a long time",2,"Since before the sun came up, and I'll be here after it goes down, probably"}},
{"fw_ld7_pma_0025","panic_days",2,"reg=civilian,family,worker,rescue,military|r1=civilian,family,worker,rescue|r2=military|day=0,4|mood=fear",{1,"What did you see that made your hands shake like that?",2,"Nothing",1,"That's not nothing, I can see you!",2,"...a man I knew from basic, sitting on the ground, he was one of them, I had to"}},
{"fw_ld7_pma_0026","panic_days",2,"reg=civilian,family,worker,rescue,military|r1=civilian,family,worker,rescue|r2=military|x1=f|day=0,4|mood=grim",{1,"Are the helicopters bringing in medics?",2,"I don't see any",1,"What are they carrying?",2,"I don't know, ma'am, they come in low, they leave low, we don't get to ask"}},
{"fw_ld7_pma_0027","panic_days",2,"reg=civilian,family,worker,rescue,military|r1=civilian,family,worker,rescue|r2=military|day=0,4|mood=angry",{1,"My neighbor says you boys are sitting on a pallet of food",2,"Your neighbor's wrong",1,"He says it's behind the school!",2,"Then he's welcome to go look, I'll write him a pass to enjoy the view"}},
{"fw_ld7_pma_0028","panic_days",2,"reg=civilian,family,worker,rescue,military|r1=civilian,family,worker,rescue|r2=military|x1=f|day=0,4|mood=fear",{1,"What's a MOPP suit? Somebody said you've got special suits?",2,"Chemical gear",1,"Is it chemical? Is that what's happening?",2,"Nobody's said that, ma'am, but nobody's said it isn't either, and that's about the worst I can tell you"}},
{"fw_ld7_pma_0029","panic_days",2,"reg=civilian,family,worker,rescue,military|r1=civilian,family,worker,rescue|r2=military|day=0,4|mood=sad",{1,"Do you have kids?",2,"Yes",1,"Where?",2,"Ohio, with their mother, I haven't been able to call, I've tried every payphone on base"}},
{"fw_ld7_pma_0030","panic_days",2,"reg=civilian,family,worker,rescue,military|r1=civilian,family,worker,rescue|r2=military|x1=f|day=0,4|mood=angry",{1,"You don't have any answers at all, do you?",2,"No",1,"Don't you feel bad about that?",2,"Every minute I'm awake, ma'am, I just don't see how saying it out loud helps"}},
{"fw_ld7_pma_0031","panic_days",2,"reg=civilian,family,worker,rescue,military|r1=civilian,family,worker,rescue|r2=military|day=0,4|mood=fear",{1,"Is it okay if we stay near your trucks?",2,"Stay behind the second one, that's the shortest line of fire",1,"Line of fire for what?",2,"For anything coming from that side, don't look, just stay down"}},
{"fw_ld7_pma_0032","panic_days",2,"reg=civilian,family,worker,rescue,military|r1=civilian,family,worker,rescue|r2=military|day=0,4|mood=grim",{1,"How do I know you're even real Army?",2,"What?",1,"There's people dressed like soldiers who aren't, I heard",2,"Then look at my boots, they're a size too big and I've had the same blisters for three days"}},
{"fw_ld7_pma_0033","panic_days",2,"reg=civilian,family,worker,rescue,military|r1=civilian,family,worker,rescue|r2=military|tmp=fresh|day=0,4|mood=fear",{1,"Please don't shoot, please don't, I'm one of the good ones, I'm a person!",2,"Nobody's shooting, show me your hands, real slow",1,"They're up, they're up, look, I'm not bit!",2,"Okay, come toward me, nice and slow, don't run, never run"}},
{"fw_ld7_pma_0034","panic_days",2,"reg=civilian,family,worker,rescue,military|r1=civilian,family,worker,rescue|r2=military|day=0,4|mood=sad",{1,"What do you do when they're someone you know?",2,"Same as when they're not",1,"How?",2,"I shut my eyes for half a second, and then I don't"}},
{"fw_ld7_pma_0035","panic_days",2,"reg=civilian,family,worker,rescue,military|r1=civilian,family,worker,rescue|r2=military|x1=f|day=0,4|mood=fear",{1,"Where's the nearest safe place?",2,"Honestly, ma'am, I don't have one",1,"Not even a guess?",2,"The fort was supposed to be it, and that was a mistake"}},
{"fw_ld7_pma_0036","panic_days",2,"reg=civilian,family,worker,rescue,military|r1=civilian,family,worker,rescue|r2=military|day=0,4|mood=angry",{1,"I'm a taxpayer, I pay your salary!",2,"I know it, I'd quit if I could",1,"Why can't you?",2,"Because it's a hundred and four miles to anywhere I'd rather be, and I'd have to run past all of them"}},
{"fw_ld7_pma_0037","panic_days",2,"reg=civilian,family,worker,rescue,military|r1=civilian,family,worker,rescue|r2=military|day=0,4|mood=sad",{1,"Is it true some of you walked off?",2,"Yes",1,"Why?",2,"One of 'em said he was going to find his wife, nobody tried to stop him"}},
{"fw_ld7_pma_0038","panic_days",2,"reg=civilian,family,worker,rescue,military|r1=civilian,family,worker,rescue|r2=military|day=0,4|mood=fear",{1,"You sound scared",2,"I am",1,"I thought soldiers weren't scared",2,"Scared all the same, they just drilled me to move anyway"}},
{"fw_ld7_pma_0039","panic_days",2,"reg=civilian,family,worker,rescue,military|r1=civilian,family,worker,rescue|r2=military|x1=f|day=0,4|mood=grim",{1,"How long do you think we've got?",2,"Till what?",1,"Until it comes down to us, until there's nobody left but us",2,"I quit counting around noon, ma'am"}},
{"fw_ld7_pma_0040","panic_days",2,"reg=civilian,family,worker,rescue,military|r1=civilian,family,worker,rescue|r2=military|day=0,4|mood=fear",{1,"Should we get in the storm shelter out back?",2,"Probably",1,"Probably?! You don't KNOW?",2,"One way in, one way out, which is great right up until it isn't"}},
{"fw_ld7_pma_0041","panic_days",3,"reg=civilian,family,worker,rescue,military|r1=civilian,family,worker,rescue|r2=civilian,family,worker,rescue|r3=military|day=0,4|mood=angry",{1,"He's not letting us through, I told you he wouldn't",2,"I'm trying to find my brother!",3,"I have a brother too, and I'm still not letting you through",1,"That's not fair!",3,"No, it's not fair, not one bit of it, turn around"}},
